// Stage 2, Path A: search returned nothing useful -> tell the human plainly instead of proceeding on weak results.
const requestId = $('A1 · Fetch Request Row').first().json.id;
const results = $json.results || [];

if (results.length === 0) {
  return [{ json: { requestId, noResults: true } }];
}

return [{
  json: {
    requestId,
    noResults: false,
    sources: results.map(r => ({
      request_id: requestId,
      url: r.url,
      title: r.title || null,
      status: 'pending_selection'
    }))
  }
}];

const source = $('A2 · Loop Over Selected Sources').item.json;
const response = $json;
const text = (response.data?.markdown || '').trim();

// Near-empty text (a JS shell) is treated as a failure, not a success, or it silently poisons grounding.
const MIN_SUBSTANTIVE_CHARS = 200;
const success = response.success === true && text.length >= MIN_SUBSTANTIVE_CHARS;

return [{
  json: {
    id: source.id,
    url: source.url,
    success,
    scraped_text: success ? text : null,
    fetch_error: success ? null : (response.error || (text.length > 0 ? 'Scrape returned near-empty text (likely a JS-rendered shell).' : 'Firecrawl scrape failed or returned no content.'))
  }
}];

