const toolUse = $json.content.find(c => c.type === 'tool_use');
const result = toolUse.input;
const requestId = $('A2 · Fetch Request Row').first().json.id;

// Claude intermittently returns a nested tool-input value as a JSON string rather
// than nesting it - confirmed live on Workflow B's excerpts ('excerpts.map is not
// a function') and three times on Workflow D's per_channel/channels. `angles` is
// consumed downstream by A2 - Insert Angle(s) as $json.angles.map(...) inside an
// n8n expression, where the same failure would be far harder to read, so it gets
// normalised to a real array of objects here at the boundary instead.
let angles = result.angles;
if (typeof angles === 'string') { try { angles = JSON.parse(angles); } catch { angles = []; } }
if (!Array.isArray(angles)) angles = [];
angles = angles.filter(a => a && typeof a === 'object');

return [{ json: { requestId, ...result, angles } }];

// alwaysOutputData on the upstream fetch forces a fake placeholder item ({}) when the
// real result is genuinely empty (zero rows) - filter that out before counting, or a
// zero-row case gets miscounted as count:1 and a fake empty 'source' flows downstream.
const items = $input.all().filter(i => i.json && i.json.id);
return [{ json: { count: items.length, sources: items.map(i => i.json) } }];

const needingScrape = ($json.sources || []).filter(s => s.status !== 'scraped');
if (needingScrape.length === 0) return [{ json: { skip: true } }];
return needingScrape.map(s => ({ json: s }));

// alwaysOutputData on the upstream fetch forces a fake placeholder item ({}) when the
// real result is genuinely empty (zero rows) - filter that out before counting, or a
// zero-row case gets miscounted as count:1 and a fake empty 'source' flows downstream.
const items = $input.all().filter(i => i.json && i.json.id);
return [{ json: { count: items.length, sources: items.map(i => i.json) } }];

const requestId = $('A2 · Fetch Request Row').first().json.id;
const err = $json.error || {};
const message = (err.message || JSON.stringify(err) || 'Unknown Claude API error').slice(0, 500);
return [{ json: { requestId, message } }];
